using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

// Generated by AI
// Data structure used to store cultural trivia information.
[System.Serializable]
public class CulturalTrivia
{
    public string regionName;

    [TextArea(2, 4)]
    public string culturalFact;
    public string questionText;

    [TextArea(2, 3)]
    public string hint;

    public string[] options;
    public int correctAnswerIndex;
}

public class TriviaManager : MonoBehaviour
{
    [Header("Cultural Trivia Database")]
    public List<CulturalTrivia> triviaList = new List<CulturalTrivia>();

    [Header("UI Components")]
    public GameObject triviaPanel;
    public TextMeshProUGUI regionText;
    public TextMeshProUGUI factText;
    public TextMeshProUGUI questionText;
    public TextMeshProUGUI feedbackText;
    public GameObject feedbackPanel;
    public Button retryButton;
    public Button[] optionButtons;

    [Header("Game Flow References")]
    public GameObject winScreen;
    public GameObject loseScreen;

    private CulturalTrivia currentTrivia;
    private bool triviaActive = false;

    private void Start()
    {
        if (triviaPanel != null)
            triviaPanel.SetActive(false);

        if (feedbackText != null)
            feedbackText.text = "";

        if (feedbackPanel != null)
        feedbackPanel.SetActive(false);

        if (retryButton != null)
        retryButton.onClick.AddListener(RetryQuestion);
    }

    // Shows a random trivia question after collecting all objects.
    public void TriggerEndLevelTrivia()
    {
        if (triviaActive || triviaList.Count == 0)
            return;

        triviaActive = true;
        Time.timeScale = 0f;

        triviaPanel.SetActive(true);

        int randomIndex = Random.Range(0, triviaList.Count);
        currentTrivia = triviaList[randomIndex];

        regionText.text = currentTrivia.regionName;
        factText.text = currentTrivia.culturalFact;
        questionText.text = currentTrivia.questionText;

        if (feedbackText != null)
            feedbackText.text = "";

        for (int i = 0; i < optionButtons.Length; i++)
        {
            if (i < currentTrivia.options.Length)
            {
                optionButtons[i].gameObject.SetActive(true);
                optionButtons[i].interactable = true;

                TextMeshProUGUI buttonText =
                    optionButtons[i].GetComponentInChildren<TextMeshProUGUI>();

                if (buttonText != null)
                    buttonText.text = currentTrivia.options[i];

                int selectedIndex = i;

                optionButtons[i].onClick.RemoveAllListeners();
                optionButtons[i].onClick.AddListener(
                    () => OnAnswerSelected(selectedIndex)
                );
            }
            else
            {
                optionButtons[i].gameObject.SetActive(false);
            }
        }
    }

    // Checks the selected answer and provides feedback.
    private void OnAnswerSelected(int index)
    {
        if (!triviaActive || currentTrivia == null)
            return;

        if (index == currentTrivia.correctAnswerIndex)
        {
            triviaActive = false;
            triviaPanel.SetActive(false);

            GameController controller = FindFirstObjectByType<GameController>();

            if (controller != null)
                controller.Ganar();
        }
       else
        {
            if (feedbackPanel != null)
                feedbackPanel.SetActive(true);

            if (feedbackText != null)
            {
                feedbackText.text =
                    "¡No exactamente!\n\n" +
                    "Pista: " + currentTrivia.hint +
                    "\n\n¡Inténtalo nuevamente!";
            }

            foreach (Button button in optionButtons)
            {
                button.interactable = false;
            }
        }
    }
        private void RetryQuestion()
    {
        if (feedbackPanel != null)
        feedbackPanel.SetActive(false);

        if (feedbackText != null)
        feedbackText.text = "";

        foreach (Button button in optionButtons)
        {
        button.interactable = true;
        }
    }
}
